import com.sun.source.util.JavacTask;
import java.io.*;
import java.net.URI;
import java.nio.file.*;
import java.util.*;

// ROUTE A1 for java: the compiler's OWN checker, called in process
// through javax.tools, one JVM for the whole run.  JavacTask.analyze()
// runs parse + enter + attribute + flow and STOPS before code
// generation, so nothing is emitted; the verdict is javac's own
// diagnostic list, not a reading of it.
public class JDrv {
  static class Src extends SimpleJavaFileObject {
    final String code;
    Src(String name, String code) {
      super(URI.create("string:///" + name + ".java"), Kind.SOURCE);
      this.code = code;
    }
    public CharSequence getCharContent(boolean ignore) { return code; }
  }
  static class MemOut extends SimpleJavaFileObject {
    MemOut(String n) { super(URI.create("mem:///" + n + ".class"), Kind.CLASS); }
    public OutputStream openOutputStream() { return new ByteArrayOutputStream(); }
  }
  public static void main(String[] a) throws Exception {
    List<String> files = Files.readAllLines(Paths.get(a[0]));
    JavaCompiler c = ToolProvider.getSystemJavaCompiler();
    if (c == null) { System.out.println("__NOTE__|NO_SYSTEM_COMPILER"); return; }
    StandardJavaFileManager sfm = c.getStandardFileManager(null, null, null);
    JavaFileManager fm = new ForwardingJavaFileManager<StandardJavaFileManager>(sfm) {
      public JavaFileObject getJavaFileForOutput(Location l, String n,
          JavaFileObject.Kind k, FileObject s) { return new MemOut(n); }
    };
    List<String> opts = Arrays.asList("-proc:none", "-nowarn");
    check(c, fm, opts, "W", "class W { int f() { return 1; } }");
    long t0 = System.currentTimeMillis();
    int n = 0;
    for (String f : files) {
      if (f.isEmpty()) continue;
      String name = new File(f).getName();
      String base = name.substring(0, name.length() - 5);
      boolean ok;
      try {
        ok = check(c, fm, opts, base,
                   new String(Files.readAllBytes(Paths.get(f))));
      } catch (Throwable t) { ok = false; }
      System.out.println(base + "|" + (ok ? "ACCEPT" : "REFUSE"));
      n++;
      if ((n % 2000) == 0) System.out.flush();
    }
    System.out.println("__TOTAL_MS__|" + (System.currentTimeMillis()-t0) + "|" + n);
    System.out.flush();
  }
  static boolean check(JavaCompiler c, JavaFileManager fm, List<String> opts,
                       String base, String code) throws Exception {
    DiagnosticCollector<JavaFileObject> dc = new DiagnosticCollector<>();
    JavacTask t = (JavacTask) c.getTask(new PrintWriter(new StringWriter()),
        fm, dc, opts, null, Arrays.asList(new Src(base, code)));
    try { t.analyze(); } catch (Throwable e) { /* diagnostics decide */ }
    for (Diagnostic<? extends JavaFileObject> d : dc.getDiagnostics())
      if (d.getKind() == Diagnostic.Kind.ERROR) return false;
    return true;
  }
}
''')
